280	
281	static int skw_send(FAR struct sdio_dev_s *sdio, uint8_t channel,
282	                    FAR const char *msg, size_t size)
283	{
284	  uint8_t pkt[SKW_BLK_SIZE];
285	  uint32_t hdr;
286	  size_t count = (size + 3) & ~3;
287	
288	  if (count + 8 > sizeof(pkt))
289	    {
290	      return -E2BIG;
291	    }
292	
293	  memset(pkt, 0, sizeof(pkt));
294	  hdr = (uint32_t)count | (uint32_t)channel << 24;
295	  memcpy(pkt, &hdr, 4);
296	  memcpy(pkt + 4, msg, size);
297	  hdr = 1u << 23;                                  /* eof */
298	  memcpy(pkt + 4 + count, &hdr, 4);
299	
300	  return sdio_io_rw_extended(sdio, true, SKW_FUNCTION, SKW_PK_WINDOW,
301	                             false, pkt, SKW_BLK_SIZE, 0);
302	}
