327	/* skw_sdio2_sdma_parser + skw_sdio2_handle_packet.  Every non-ack packet
328	 * carries a 12-byte sub-header after the 4-byte header; the payload is at
329	 * +16 and is len - 12 bytes.  A 12-byte packet is the CP's TX ack.
330	 */
331	
332	static void skw_parse(FAR struct skw_ctx_s *ctx, unsigned int npac)
333	{
334	  unsigned int i;
335	
336	  for (i = 0; i < npac; i++)
337	    {
338	      FAR uint8_t *p = ctx->rxbuf + i * SKW_PAC_SIZE;
339	      uint32_t hdr = skw_le32(p);
340	      unsigned int len = hdr & 0xffff;
341	      unsigned int ch = hdr >> 24;
342	      FAR const uint8_t *pl = p + 16;
343	      size_t plen;
344	
345	      if ((hdr >> 23) & 1)
346	        {
347	          break;
348	        }
349	
350	      if (len < 12 || len > SKW_PAC_SIZE - 4)
351	        {
352	          syslog(LOG_WARNING, "SKW6621S: rx bad header 0x%08" PRIx32 "\n",
353	                 hdr);
354	          break;
355	        }
356	
357	      if (len == 12)
358	        {
359	          ctx->acks++;
360	          continue;
361	        }
362	
363	      plen = len - 12;
364	
365	      if (ch == SKW_LOOPCHECK_CH)
366	        {
367	          char cmd[96];
368	          size_t n = plen < sizeof(cmd) - 1 ? plen : sizeof(cmd) - 1;
369	
370	          memcpy(cmd, pl, n);
371	          cmd[n] = '\0';
372	          syslog(LOG_INFO, "SKW6621S: LOOPCHECK \"%s\"\n", cmd);
373	
374	          if (strncmp(cmd, "BSPREADY", 8) == 0)
375	            {
376	              int ret = skw_send(ctx->sdio, SKW_LOOPCHECK_CH, "RDVERSION", 9);
377	              syslog(LOG_INFO, "SKW6621S: sent RDVERSION: %d\n", ret);
378	            }
379	          else if (strncmp(cmd, "trunk_W", 7) == 0)
380	            {
381	              ctx->flags |= SKW_FLAG_VERSION;
382	            }
383	          else if (strncmp(cmd, "BTREADY", 7) == 0)
384	            {
385	              ctx->flags |= SKW_FLAG_BTREADY;
386	            }
387	          else if (strncmp(cmd, "BSPASSERT", 9) == 0)
388	            {
389	              ctx->flags |= SKW_FLAG_ASSERT;
390	            }
391	
392	          continue;
393	        }
394	
395	      if ((ch == SKW_BT_CMD_CH || ch == SKW_BT_DATA_CH) && plen >= 1)
396	        {
397	          /* H4: first byte is the packet type; 0x07 is the CP's log */
398	
399	          if (pl[0] == 0x07)
400	            {
401	              continue;
402	            }
403	
404	          if (ctx->cb != NULL)
405	            {
406	              ctx->cb(ctx->cbarg, pl[0], pl + 1, plen - 1);
407	            }
408	          else
409	            {
410	              syslog(LOG_INFO, "SKW6621S: ch %u type %02x len %zu\n",
411	                     ch, pl[0], plen - 1);
412	            }
413	
414	          continue;
415	        }
416	
417	      syslog(LOG_INFO, "SKW6621S: rx ch %u len %u (dropped)\n", ch, len);
418	    }
419	}
