421	/* One RX pass under the lock: read only if F1 interrupt is pending, and
422	 * keep reading while the CP says more packets follow.
423	 */
424	
425	static int skw_rx_once(FAR struct skw_ctx_s *ctx)
426	{
427	  uint8_t pend;
428	  int loops = 0;
429	  int ret;
430	
431	  ret = skw_f0_read(ctx->sdio, SKW_CCCR_INTPEND, &pend);
432	  if (ret < 0 || (pend & 0x02) == 0)
433	    {
434	      return ret < 0 ? ret : 0;
435	    }
436	
437	  do
438	    {
439	      unsigned int n = ctx->npac;
440	      size_t len = SKW_PAC_SIZE * n + SKW_BLK_SIZE;
441	      uint32_t nsize;
442	
443	      ret = sdio_io_rw_extended(ctx->sdio, false, SKW_FUNCTION,
444	                                SKW_PK_WINDOW, false, ctx->rxbuf,
445	                                SKW_BLK_SIZE, len / SKW_BLK_SIZE);
446	      if (ret < 0)
447	        {
448	          syslog(LOG_ERR, "SKW6621S: rx read %zu: %d\n", len, ret);
449	          return ret;
450	        }
451	
452	      nsize = skw_le32(ctx->rxbuf + len - 4);
453	      skw_parse(ctx, n);
454	
455	      ctx->npac = nsize == 0 ? 1 :
456	                  nsize > SKW_RX_MAX_PAC ? SKW_RX_MAX_PAC : nsize;
457	      if (nsize == 0)
458	        {
459	          break;
460	        }
461	    }
462	  while (++loops < 16);
463	
464	  return 1;
465	}
