467	/* Poll until a flag shows up, bounded */
468	
469	static int skw_wait_flag(FAR struct skw_ctx_s *ctx, uint32_t flag,
470	                         unsigned int timeout_ms)
471	{
472	  clock_t start = clock_systime_ticks();
473	  int ret;
474	
475	  while (TICK2MSEC(clock_systime_ticks() - start) < timeout_ms)
476	    {
477	      nxmutex_lock(&ctx->lock);
478	      ret = skw_rx_once(ctx);
479	      nxmutex_unlock(&ctx->lock);
480	
481	      if (ret < 0)
482	        {
483	          return ret;
484	        }
485	
486	      if (ctx->flags & SKW_FLAG_ASSERT)
487	        {
488	          return -EIO;
489	        }
490	
491	      if (ctx->flags & flag)
492	        {
493	          return OK;
494	        }
495	
496	      if (ret == 0)
497	        {
498	          up_mdelay(SKW_POLL_MS);
499	        }
500	    }
501	
502	  return -ETIMEDOUT;
503	}
