542	    {
543	      ret = skw_load(dir, "SWT6621S_DRAM_SDIO.bin", &dram);
544	    }
545	
546	  if (ret == OK)
547	    {
548	      ret = skw_load(dir, nvname, &nv);
549	    }
550	
551	  if (ret == OK)
552	    {
553	      ret = skw_prepare(&iram, &nv, &iram_addr, &dram_addr);
554	    }
555	
556	  if (ret == OK && ctx->rxbuf == NULL)
557	    {
558	      ctx->rxbuf = kmm_malloc(SKW_RX_BUF_SIZE);
559	      ret = ctx->rxbuf == NULL ? -ENOMEM : OK;
560	    }
561	
562	  if (ret < 0)
563	    {
564	      goto out;
565	    }
566	
567	  nxmutex_lock(&ctx->lock);
568	  ctx->sdio = sdio;
569	  ctx->npac = 1;
570	  ctx->flags = 0;
571	  ctx->acks = 0;
572	
573	  /* skw_sdio_set_dma_type / skw_sdio_slp_feature_en.  K7 has no
574	   * host/chip wake GPIOs, so the SDK would disable CP sleep.
