581	    }
582	
583	  /* Function 1 + master interrupt enable, and async interrupt, so that
584	   * CCCR INT pending reflects CP data even though we only poll it.
585	   */
586	
587	  if (ret == OK)
588	    {
589	      ret = skw_f0_write(sdio, SKW_CCCR_INTEN, 0x03);
590	    }
591	
592	  if (ret == OK && skw_f0_read(sdio, SKW_SDIO_INT_EXT, &reg) == OK)
593	    {
594	      ret = skw_f0_write(sdio, SKW_SDIO_INT_EXT, reg | 0x02);
595	    }
596	
597	  if (ret < 0)
598	    {
599	      nxmutex_unlock(&ctx->lock);
600	      syslog(LOG_ERR, "SKW6621S: pre-download config: %d\n", ret);
601	      goto out;
602	    }
603	
604	  start = clock_systime_ticks();
605	  ret = skw_dt_write(sdio, dram_addr, dram.data, dram.size);
606	  if (ret == OK)
607	    {
608	      ret = skw_dt_write(sdio, iram_addr, iram.data, iram.size);
609	    }
610	
611	  if (ret == OK)
612	    {
613	      syslog(LOG_INFO, "SKW6621S: download done in %u ms\n",
614	             (unsigned int)TICK2MSEC(clock_systime_ticks() - start));
