183	
184	static uint16_t skw_le16(FAR const uint8_t *p)
185	{
186	  return p[0] | p[1] << 8;
187	}
188	
189	/* skw_event_scan_report: skw_mgmt_hdr (chan, band, s16 signal, u16 len,
190	 * u16 resv) then a beacon / probe response; IEs start 36 bytes into it.
191	 */
192	
193	static void wifi_scan_report(FAR const uint8_t *data, size_t len)
194	{
195	  FAR const uint8_t *mgmt = data + 8;
196	  FAR const uint8_t *ie;
197	  FAR struct skw_bss_s *bss = NULL;
198	  size_t mlen;
199	  size_t off;
200	  unsigned int i;
201	
202	  g_nreport++;
203	  if (len < 8 + 36)
204	    {
205	      return;
206	    }
207	
208	  mlen = skw_le16(data + 4);
209	  if (mlen > len - 8)
210	    {
211	      mlen = len - 8;
212	    }
213	
214	  if (mlen < 36)
215	    {
216	      return;
217	    }
218	
219	  for (i = 0; i < g_nbss; i++)
220	    {
221	      if (memcmp(g_bss[i].bssid, mgmt + 16, 6) == 0)
222	        {
223	          bss = &g_bss[i];
224	          break;
225	        }
226	    }
227	
228	  if (bss == NULL)
229	    {
230	      if (g_nbss >= SKW_SCAN_MAX_BSS)
231	        {
232	          return;
233	        }
234	
235	      bss = &g_bss[g_nbss++];
236	      memset(bss, 0, sizeof(*bss));
237	      memcpy(bss->bssid, mgmt + 16, 6);
238	    }
239	
240	  bss->chan = data[0];
241	  bss->signal = (int16_t)skw_le16(data + 2);
242	
243	  ie = mgmt + 36;
244	  for (off = 0; off + 2 <= mlen - 36; off += 2 + ie[off + 1])
245	    {
246	      if (ie[off] == 0 && off + 2 + ie[off + 1] <= mlen - 36)
247	        {
248	          size_t n = ie[off + 1] < 32 ? ie[off + 1] : 32;
249	
250	          memcpy(bss->ssid, ie + off + 2, n);
251	          bss->ssid[n] = '\0';
252	          bss->ssid_len = n;
253	          break;
254	        }
255	    }
256	}
