258	static void wifi_rx_cb(FAR void *arg, uint8_t channel,
259	                       FAR const uint8_t *data, size_t len)
260	{
261	  uint8_t type;
262	  uint8_t id;
263	  uint16_t seq;
264	  size_t total;
265	
266	  if (channel != SKW_WIFI_CMD_CH || len < SKW_MSG_HDR_LEN)
267	    {
268	      return;
269	    }
270	
271	  type = data[0] >> 4;
272	  id = data[1];
273	  seq = skw_le16(data + 2);
274	  total = skw_le16(data + 4);
275	  if (total < SKW_MSG_HDR_LEN || total > len)
276	    {
277	      total = len;
278	    }
279	
280	  if (type == SKW_MSG_CMD_ACK)
281	    {
282	      if (id != g_cmd_id || seq != g_cmd_seq || total < SKW_ACK_HDR_LEN)
283	        {
284	          syslog(LOG_WARNING, "SKW WiFi: stray ack id %u seq %u\n", id, seq);
285	          return;
286	        }
287	
288	      g_cmd_status = skw_le16(data + SKW_MSG_HDR_LEN);
289	      g_cmd_rsp_len = total - SKW_ACK_HDR_LEN;
290	      if (g_cmd_rsp_len > sizeof(g_cmd_rsp))
291	        {
292	          g_cmd_rsp_len = sizeof(g_cmd_rsp);
293	        }
294	
295	      memcpy(g_cmd_rsp, data + SKW_ACK_HDR_LEN, g_cmd_rsp_len);
296	      g_cmd_acked = true;
297	    }
298	  else if (type == SKW_MSG_EVENT)
299	    {
300	      FAR const uint8_t *ev = data + SKW_MSG_HDR_LEN;
301	      size_t evlen = total - SKW_MSG_HDR_LEN;
302	
303	      switch (id)
304	        {
305	          case SKW_EVENT_SCAN_REPORT:
306	            wifi_scan_report(ev, evlen);
307	            break;
308	
309	          case SKW_EVENT_NORMAL_SCAN_CMPL:
310	            g_scan_done = true;
311	            break;
312	
313	          case SKW_EVENT_CREDIT_UPDATE:
314	            break;
315	
316	          default:
317	            syslog(LOG_INFO, "SKW WiFi: event %u len %zu\n", id, evlen);
318	            break;
319	        }
320	    }
321	  else
322	    {
323	      syslog(LOG_INFO, "SKW WiFi: rx type %u id %u len %zu\n",
324	             type, id, len);
325	    }
326	}
