328	/* skw_set_cmd + skw_msg_xmit: one command, bounded wait for its ack.
329	 * Returns the CP status (>= 0) or a negative errno.
330	 */
331	
332	static int wifi_cmd(uint8_t inst, uint8_t id, FAR const void *param,
333	                    size_t plen, FAR void *rsp, size_t rspsize,
334	                    unsigned int timeout_ms)
335	{
336	  static uint8_t msg[SKW_MSG_HDR_LEN + 1024];
337	  size_t total = SKW_MSG_HDR_LEN + plen;
338	  clock_t start;
339	  int ret;
340	
341	  if (total > sizeof(msg))
342	    {
343	      return -E2BIG;
344	    }
345	
346	  g_cmd_id = id;
347	  g_cmd_seq++;
348	  g_cmd_acked = false;
349	
350	  msg[0] = (inst & 0x0f) | SKW_MSG_CMD << 4;
351	  msg[1] = id;
352	  msg[2] = g_cmd_seq & 0xff;
353	  msg[3] = g_cmd_seq >> 8;
354	  msg[4] = total & 0xff;
355	  msg[5] = total >> 8;
356	  msg[6] = 0;
357	  msg[7] = 0;
358	  if (plen > 0)
359	    {
360	      memcpy(msg + SKW_MSG_HDR_LEN, param, plen);
361	    }
362	
363	  ret = skw6621s_wifi_xmit(SKW_WIFI_CMD_CH, msg, total);
364	  if (ret < 0)
365	    {
366	      syslog(LOG_ERR, "SKW WiFi: cmd %u xmit %d\n", id, ret);
367	      return ret;
368	    }
369	
370	  start = clock_systime_ticks();
371	  while (TICK2MSEC(clock_systime_ticks() - start) < timeout_ms)
372	    {
373	      ret = skw6621s_poll();
374	      if (ret < 0)
375	        {
376	          return ret;
377	        }
378	
379	      if (g_cmd_acked)
380	        {
381	          if (rsp != NULL)
382	            {
383	              memcpy(rsp, g_cmd_rsp,
384	                     g_cmd_rsp_len < rspsize ? g_cmd_rsp_len : rspsize);
385	              if (g_cmd_rsp_len != rspsize)
386	                {
387	                  syslog(LOG_INFO, "SKW WiFi: cmd %u rsp %zu, want %zu\n",
388	                         id, g_cmd_rsp_len, rspsize);
389	                }
390	            }
391	
392	          return g_cmd_status;
393	        }
394	
395	      if (ret == 0)
396	        {
397	          up_mdelay(2);
398	        }
399	    }
400	
401	  syslog(LOG_ERR, "SKW WiFi: cmd %u seq %u timeout\n", id, g_cmd_seq);
402	  return -ETIMEDOUT;
403	}
