405	static int wifi_load(FAR const char *path, FAR uint8_t **data,
406	                     FAR size_t *size)
407	{
408	  struct file filep;
409	  struct stat st;
410	  ssize_t nread;
411	  int ret;
412	
413	  ret = file_open(&filep, path, O_RDONLY);
414	  if (ret < 0)
415	    {
416	      return ret;
417	    }
418	
419	  ret = file_fstat(&filep, &st);
420	  if (ret == OK && (st.st_size <= 0 || st.st_size > SKW_CALIB_MAX))
421	    {
422	      ret = -EFBIG;
423	    }
424	
425	  if (ret == OK)
426	    {
427	      *data = kmm_malloc(st.st_size);
428	      ret = *data == NULL ? -ENOMEM : OK;
429	    }
430	
431	  if (ret == OK)
432	    {
433	      nread = file_read(&filep, *data, st.st_size);
434	      if (nread != st.st_size)
435	        {
436	          kmm_free(*data);
437	          *data = NULL;
438	          ret = nread < 0 ? (int)nread : -EIO;
439	        }
440	      else
441	        {
442	          *size = st.st_size;
443	        }
444	    }
445	
446	  file_close(&filep);
447	  return ret;
448	}
