450	/* skw_calib_bin_download: 512-byte chunks, seq from 0, end on the last */
451	
452	static int wifi_calib(FAR const char *path)
453	{
454	  FAR struct skw_calib_param_s *calib;
455	  FAR uint8_t *data = NULL;
456	  size_t size = 0;
457	  size_t off = 0;
458	  int seq = 0;
459	  int ret;
460	
461	  ret = wifi_load(path, &data, &size);
462	  if (ret < 0)
463	    {
464	      syslog(LOG_ERR, "SKW WiFi: load %s: %d\n", path, ret);
465	      return ret;
466	    }
467	
468	  calib = kmm_zalloc(sizeof(*calib));
469	  if (calib == NULL)
470	    {
471	      kmm_free(data);
472	      return -ENOMEM;
473	    }
474	
475	  while (off < size)
476	    {
477	      size_t n = size - off < SKW_CALIB_CHUNK ? size - off : SKW_CALIB_CHUNK;
478	
479	      calib->seq = seq;
480	      calib->len = n;
481	      calib->end = off + n >= size;
482	      memcpy(calib->data, data + off, n);
483	
484	      ret = wifi_cmd(0, SKW_CMD_PHY_BB_CFG, calib, sizeof(*calib),
485	                     NULL, 0, SKW_CALIB_TIMEOUT_MS);
486	      if (ret != 0)
487	        {
488	          syslog(LOG_ERR, "SKW WiFi: calib seq %d: %d\n", seq, ret);
489	          ret = ret > 0 ? -EIO : ret;
490	          break;
491	        }
492	
493	      off += n;
494	      seq++;
495	    }
496	
497	  syslog(LOG_INFO, "SKW WiFi: calib %s, %zu bytes, %d chunks: %d\n",
498	         path, size, seq, ret);
499	  kmm_free(calib);
500	  kmm_free(data);
501	  return ret;
502	}
