508	int skw6621s_wifi_init(FAR const char *dir)
509	{
510	  FAR struct skw_chip_info_s *chip;
511	  FAR uint8_t *ver;
512	  struct skw_open_dev_s open;
513	  char path[96];
514	  uint64_t ts;
515	  int vendor = 0;
516	  int ret;
517	  int i;
518	
519	  if (g_wifi_ready)
520	    {
521	      return OK;
522	    }
523	
524	  ret = skw6621s_wifi_start();
525	  if (ret < 0)
526	    {
527	      return ret;
528	    }
529	
530	  skw6621s_set_wifi_cb(wifi_rx_cb, NULL);
531	
532	  chip = kmm_zalloc(sizeof(*chip));
533	  ver = kmm_zalloc(512);
534	  if (chip == NULL || ver == NULL)
535	    {
536	      ret = -ENOMEM;
537	      goto out;
538	    }
539	
540	  /* skw_sync_cmd_event_version: cmd[256] + event[256] versions */
541	
542	  ret = wifi_cmd(0, SKW_CMD_SYN_VERSION, NULL, 0, ver, 512,
543	                 SKW_CMD_TIMEOUT_MS);
544	  syslog(LOG_INFO, "SKW WiFi: SYN_VERSION %d, GET_INFO v%u OPEN_DEV v%u "
545	         "START_SCAN v%u\n", ret, ver[SKW_CMD_GET_INFO],
546	         ver[SKW_CMD_OPEN_DEV], ver[SKW_CMD_START_SCAN]);
547	  if (ret != 0)
548	    {
549	      goto fail;
550	    }
551	
552	  /* skw_sync_chip_info: parameter is the host time in ms */
553	
554	  ts = TICK2MSEC(clock_systime_ticks());
555	  ret = wifi_cmd(0, SKW_CMD_GET_INFO, &ts, sizeof(ts), chip, sizeof(*chip),
556	                 SKW_CMD_TIMEOUT_MS);
557	  if (ret != 0)
558	    {
559	      goto fail;
560	    }
561	
562	  chip->fw_build_time[sizeof(chip->fw_build_time) - 1] = '\0';
563	  chip->fw_wifi_ver[sizeof(chip->fw_wifi_ver) - 1] = '\0';
564	  chip->fw_plat_ver[sizeof(chip->fw_plat_ver) - 1] = '\0';
565	  memcpy(g_mac, chip->mac, 6);
566	  syslog(LOG_INFO, "SKW WiFi: chip type 0x%" PRIx32 " module 0x%04x, "
567	         "wifi %s plat %s built %s\n", chip->fw_chip_type,
568	         chip->calib_module_id, (FAR char *)chip->fw_wifi_ver,
569	         (FAR char *)chip->fw_plat_ver, (FAR char *)chip->fw_build_time);
570	  syslog(LOG_INFO, "SKW WiFi: MAC %02x:%02x:%02x:%02x:%02x:%02x, "
571	         "bw 0x%" PRIx32 ", %u lmac\n", g_mac[0], g_mac[1], g_mac[2],
572	         g_mac[3], g_mac[4], g_mac[5], chip->fw_bw_capa,
573	         (unsigned int)(chip->priv >> 24));
574	
575	  if (chip->fw_chip_type != 0x300)
576	    {
577	      syslog(LOG_ERR, "SKW WiFi: unexpected chip type\n");
578	      ret = -ENODEV;
579	      goto out;
580	    }
581	
582	  /* CALIB_APPEND_MODULE_ID: nibble 0xf in module id -> vendor bit */
583	
584	  for (i = 0; i < 4; i++)
585	    {
586	      if (((chip->calib_module_id >> (4 * i)) & 0xf) == 0xf)
587	        {
588	          vendor |= 1 << (4 + i);
589	        }
590	    }
591	
592	  snprintf(path, sizeof(path), "%s/SWT6621S_SEEKWAVE_R%02X%03X.bin", dir,
593	           vendor & 0xff, skw6621s_revision());
594	  ret = wifi_calib(path);
595	  if (ret < 0)
596	    {
597	      goto out;
598	    }
599	
600	  /* skw_cmd_open_dev: station on inst 0 with the efuse MAC */
601	
602	  if ((g_mac[0] & 1) || (g_mac[0] | g_mac[1] | g_mac[2] |
603	                         g_mac[3] | g_mac[4] | g_mac[5]) == 0)
604	    {
605	      static const uint8_t fallback[6] =
606	      {
607	        0xfe, 0xfd, 0xfc, 0x00, 0x66, 0x21
608	      };
609	
610	      memcpy(g_mac, fallback, 6);
611	      syslog(LOG_WARNING, "SKW WiFi: efuse MAC invalid, using fallback\n");
612	    }
613	
614	  open.mode = SKW_STA_MODE;
615	  open.flags = 0;
616	  memcpy(open.mac, g_mac, 6);
617	  ret = wifi_cmd(0, SKW_CMD_OPEN_DEV, &open, sizeof(open), NULL, 0,
618	                 SKW_CMD_TIMEOUT_MS);
619	  syslog(LOG_INFO, "SKW WiFi: OPEN_DEV sta: %d\n", ret);
620	  if (ret != 0)
621	    {
622	      goto fail;
623	    }
624	
625	  g_wifi_ready = true;
626	  goto out;
627	
628	fail:
629	  ret = ret > 0 ? -EIO : ret;
630	
631	out:
632	  kmm_free(chip);
633	  kmm_free(ver);
634	  return ret;
635	}
