637	int skw6621s_wifi_scan(void)
638	{
639	  uint8_t buf[sizeof(struct skw_scan_param_s) + 13 * 3 + 33];
640	  FAR struct skw_scan_param_s *param = (FAR struct skw_scan_param_s *)buf;
641	  FAR uint8_t *chan = buf + sizeof(*param);
642	  clock_t start;
643	  unsigned int i;
644	  int ret;
645	
646	  if (!g_wifi_ready)
647	    {
648	      return -ENODEV;
649	    }
650	
651	  /* skw_scan: 2.4 GHz channels 1-13, one wildcard SSID (active) */
652	
653	  memset(buf, 0, sizeof(buf));
654	  param->nr_chan = 13;
655	  param->chan_offset = sizeof(*param);
656	  for (i = 0; i < 13; i++)
657	    {
658	      chan[i * 3] = i + 1;
659	      chan[i * 3 + 1] = 0;             /* SKW_BAND_2GHZ */
660	      chan[i * 3 + 2] = 0;
661	    }
662	
663	  param->n_ssid = 1;
664	  param->ssid_offset = sizeof(*param) + 13 * 3;
665	
666	  g_nbss = 0;
667	  g_nreport = 0;
668	  g_scan_done = false;
669	
670	  ret = wifi_cmd(0, SKW_CMD_START_SCAN, buf, sizeof(buf), NULL, 0,
671	                 SKW_CMD_TIMEOUT_MS);
672	  if (ret != 0)
673	    {
674	      syslog(LOG_ERR, "SKW WiFi: START_SCAN %d\n", ret);
675	      return ret > 0 ? -EIO : ret;
676	    }
677	
678	  start = clock_systime_ticks();
679	  while (!g_scan_done &&
680	         TICK2MSEC(clock_systime_ticks() - start) < SKW_SCAN_TIMEOUT_MS)
681	    {
682	      ret = skw6621s_poll();
683	      if (ret < 0)
684	        {
685	          return ret;
686	        }
687	
688	      if (ret == 0)
689	        {
690	          up_mdelay(5);
691	        }
692	    }
693	
694	  printf("scan %s in %u ms: %u reports, %u BSS\n",
695	         g_scan_done ? "done" : "TIMEOUT",
696	         (unsigned int)TICK2MSEC(clock_systime_ticks() - start),
697	         g_nreport, g_nbss);
698	
699	  for (i = 0; i < g_nbss; i++)
700	    {
701	      FAR struct skw_bss_s *b = &g_bss[i];
702	
703	      printf("  %02x:%02x:%02x:%02x:%02x:%02x  ch %2u  %4d dBm  %s\n",
704	             b->bssid[0], b->bssid[1], b->bssid[2], b->bssid[3],
705	             b->bssid[4], b->bssid[5], b->chan, b->signal,
706	             b->ssid_len ? b->ssid : "<hidden>");
707	    }
708	
709	  return g_scan_done ? OK : -ETIMEDOUT;
710	}
