static int wifi_tx_frame(FAR const uint8_t *dst, uint16_t proto,
                         FAR const uint8_t *payload, size_t plen)
{
  static uint8_t buf[8 + SKW_FRAME_MAX];
  size_t mlen = ETH_HLEN + plen;
  uint8_t peer = (dst[0] & 1) ? g_join.multicast_idx : g_join.peer_idx;
  uint16_t w0;
  uint16_t w1;
