  w0 = (g_join.inst & 0x3) << 2 | (peer & 0x1f) << 8;  /* tid 0, ether */
  w1 = (mlen & 0xfff) | (g_join.lmac_id & 0x3) << 12;

  buf[0] = w0 & 0xff;
  buf[1] = w0 >> 8;
  buf[2] = w1 & 0xff;
  buf[3] = w1 >> 8;
  buf[4] = proto >> 8;                  /* eth_type, network order */
  buf[5] = proto & 0xff;
  buf[6] = 0;
  buf[7] = 0;
