static int wlan_transmit(FAR struct netdev_lowerhalf_s *dev,
                         FAR netpkt_t *pkt)
{
  unsigned int len = netpkt_getdatalen(dev, pkt);
  int ret;

  if (!g_connected || len < ETH_HLEN || len > SKW_FRAME_MAX)
    {
      return -ENETDOWN;
