  ret = netpkt_tryadd_queue(pkt, &g_rxq);
  spin_unlock_irqrestore(&g_rxq_lock, flags);
  if (ret < 0)
    {
      netpkt_free(dev, pkt, NETPKT_RX);
      NETDEV_RXDROPPED(&dev->netdev);
      return;
    }

