/****************************************************************************
 * Name: xhci_slot_init
 *
 * Description:
 *   Initialzie Device Slot data.
 *
 * Assumption:
 *   1. All slot resources already allocated.
 *   2. Port is in Enabled state.
 *
 * Reference:
 *   - 4.3.3. Device Slot Initialization
 *
 ****************************************************************************/

static int xhci_slot_init(FAR struct usbhost_xhci_s *priv,
                          FAR struct xhci_dev_s *dev)
{
  FAR struct usbhost_hubport_s *hport = dev->hport;
  uint32_t                      regval;
  uint16_t                      maxpkt;
  uintptr_t                     drdp;
#ifdef CONFIG_USBHOST_HUB
  FAR struct usbhost_hubport_s *child;
  FAR struct usbhost_hubport_s *parent;
  FAR struct xhci_dev_s        *hub;
  uint32_t                      route = 0;
#endif

  DEBUGASSERT(hport != NULL && dev->rhport != NULL);

  /* Step 1. The Input Context data structure already allocated.
   * Initialize all fields to 0.
   */

  memset(dev->input, 0, sizeof(struct xhci_input_dev_ctx_s));

  /* Step 2. Initialize the Input Control Context by setting the A0 and
   * A1 flags to 1 (Slot flag and EP0 flag).
   */

  regval = XHCI_IN_CTX1_A(XHCI_SLOT_FLAG) |
           XHCI_IN_CTX1_A(XHCI_EP0_FLAG);
  xhci_context_ctrl(priv, dev, 0, regval);

  /* Step 3. Initialize the Input Slot Context */

  regval = XHCI_ST_CTX0_CTXENT_SET(1) |
           XHCI_ST_CTX0_SPEED_SET(xhci_speed_id(hport->speed));

#ifdef CONFIG_USBHOST_HUB
  /* Route string: one nibble per hub tier below the root hub port, the
   * tier closest to the root in the lowest nibble.
   */

  for (child = hport; !ROOTHUB(child); child = child->parent)
    {
      route = (route << 4) | MIN(HPORT(child), 15);
    }

  regval |= XHCI_ST_CTX0_RTSTR_SET(route);
#endif

  dev->input->slot.ctx[0] = htole32(regval);

  /* Configure Root Hub Port Number (starts from 1).  The number of ports
   * is set later if the device turns out to be a hub.
   */

  regval = XHCI_ST_CTX1_RHPN_SET(RHPNDX(dev->rhport) + 1);
  dev->input->slot.ctx[1] = htole32(regval);

#ifdef CONFIG_USBHOST_HUB
  /* A low- or full-speed device below a high-speed hub talks through the
   * transaction translator of the nearest high-speed hub.
   */

  if (hport->speed == USB_SPEED_LOW || hport->speed == USB_SPEED_FULL)
    {
      child = hport;
      for (parent = hport->parent;
           parent != NULL && parent->speed != USB_SPEED_HIGH;
           parent = parent->parent)
        {
          child = parent;
        }

      if (parent != NULL)
        {
          hub = xhci_dev_get(priv, parent->ep0);
          if (hub == NULL)
            {
              return -ENODEV;
            }

          regval = XHCI_ST_CTX2_TTHUB_SET(hub->slot) |
                   XHCI_ST_CTX2_TTPORT_SET(HPORT(child));
          dev->input->slot.ctx[2] = htole32(regval);
        }
    }
#endif

  /* Step 4. the Transfer Ring for the Default Control Endpoint is already
   * allocated.
   */

  drdp = up_addrenv_va_to_pa(dev->epinfo[0]->td.ring);

  /* Step 5. Initialize the Input default control Endpoint 0 Context */

  if (hport->speed == USB_SPEED_SUPER || hport->speed == USB_SPEED_SUPER_PLUS)
    {
      maxpkt = 512;
    }
  else if (hport->speed == USB_SPEED_HIGH)
    {
      /* For high-speed, we must use 64 bytes */

      maxpkt = 64;
    }
  else
    {
      /* Eight will work for both low- and full-speed */

      maxpkt = 8;
    }

  DEBUGASSERT(drdp != 0);
  xhci_ep_configure(priv,
                    &dev->input->ep[0],
                    XHCI_EPTYPE_CTRL, maxpkt,
                    0, drdp,
                    0, 0);

  /* Step 6. The output Device Context data structure already allocated.
   * Initialize all fields to 0.
   */

  memset(dev->ctx, 0, sizeof(struct xhci_dev_ctx_s));

  /* Flush Device input context */

  up_flush_dcache((uintptr_t)dev->input,
                  (uintptr_t)dev->input +
                  sizeof(struct xhci_input_dev_ctx_s));

  /* Step 7. Load the appropriate (Device Slot ID) entry in the Device
   * Context Base Address Array with a pointer to the Output Device
   * Context data structure
   */

  xhci_dcbaa_set(priv, dev->slot, up_addrenv_va_to_pa(dev->ctx));

  return OK;
}

/****************************************************************************
 * Name: xhci_device_init
 *
 * Description:
 *   Initialzie Device attached to hport, using ep0 as its Default Control
 *   Endpoint.
 *
 * Assumption:
 *   1. All device resources already allocated.
 *   2. Port is in Enabled state.
 *
 * Reference:
 *   - 4.3: USB Device Initialization
 *
 ****************************************************************************/

static int xhci_device_init(FAR struct usbhost_xhci_s *priv,
                            FAR struct xhci_rhport_s *rhport,
                            FAR struct usbhost_hubport_s *hport,
                            FAR struct xhci_epinfo_s *ep0)
{
  FAR struct xhci_dev_s *dev;
  uint8_t                slot;
  int                    ret;

  DEBUGASSERT(ep0 != NULL && ep0->slot == 0);

  /* We entry this function after steps 1-3 from "USB Device Initialization"
   * are done.
   */

  /* Step 4: Get Device Slot.
   *
   * Reference:
   *   - 4.3.2: Device Slot Assignment
   */

  ret = xhci_cmd_sloten(priv, &slot);
  if (ret < 0 || slot == 0 || slot > priv->no_slots)
    {
      /* Something goes wrong ! */

      usbhost_vtrace1(XHCI_TRACE1_SLOTEN_FAILED, ret);
      return ret < 0 ? ret : -ENOMEM;
    }

  /* Slot ID is an index to that identify Device data */

  dev = &priv->devs[slot - 1];

  /* Slot has been allocated to software and is now in Enabled state */

  dev->state     = XHCI_SLOT_ENABLED;
  dev->rhport    = rhport;
  dev->hport     = hport;
  dev->slot      = slot;
  dev->epinfo[0] = ep0;
  ep0->slot      = slot;

  /* Step 5: Initialize the data structures associated with the slot.
   * All data structured are already allocated.
   */

  ret = xhci_ring_init(&ep0->td, XHCI_TD_MAX);
  if (ret < 0)
    {
      pcierr("ep0 ring init failed\n");
      goto errout;
    }

  ret = xhci_slot_init(priv, dev);
  if (ret < 0)
    {
      goto errout;
    }

  /* Step 6: Assing and address to the device and enable its Default
   * Control Endpoint.
   *
   * NOTE: we don't send SET_ADDRESS request here.
   *       This is done in xhci_ctrlin() and controlled by NuttX USB Host
   *       stack.
   */

  ret = xhci_address_set(priv, dev, false);
  if (ret < 0)
    {
      pcierr("failed to set address %d\n", ret);
      goto errout;
    }

  /* Steps 7-12 don't belong here! */

  return OK;

errout:
  xhci_device_deinit(priv, dev);
  return ret;
}

/****************************************************************************
 * Name: xhci_device_deinit
 *
 * Description:
 *   Free Device.
 *
 * Reference:
 *   - 4.3: USB Device Initialization
 *
 ****************************************************************************/

static int xhci_device_deinit(FAR struct usbhost_xhci_s *priv,
                              FAR struct xhci_dev_s *dev)
{
  uint8_t slot = dev->slot;
  int     ret;
  int     i;

  /* Disable Slot */

  ret = xhci_cmd_slotdis(priv, slot);
  if (ret < 0)
    {
      pcierr("xhci_cmd_slotdis failed %d\n", ret);
    }

  /* Clear DCBAA entry for this slot */

  xhci_dcbaa_set(priv, slot, 0);

  /* Clean up device data, but don't touch allocated memory!  Endpoints
   * still owned by class drivers are detached from the slot, so late
   * transfer events and epfree() don't touch a reused slot.
   */

  for (i = 0; i < XHCI_MAX_ENDPOINTS; i++)
    {
      if (dev->epinfo[i] != NULL)
        {
          dev->epinfo[i]->slot = 0;
          dev->epinfo[i] = NULL;
        }
    }

  dev->state  = XHCI_SLOT_DISABLED;
  dev->hport  = NULL;
  dev->rhport = NULL;

  memset(dev->ctx, 0, sizeof(struct xhci_dev_ctx_s));
  memset(dev->input, 0, sizeof(struct xhci_input_dev_ctx_s));

  return OK;
}

#ifdef CONFIG_USBHOST_HUB
/****************************************************************************
 * Name: xhci_hub_update
 *
 * Description:
 *   Tell the xHC that a device is a hub, once its hub descriptor is known.
 *   Configure Endpoint with only the Slot Context added evaluates the Hub,
 *   Number of Ports and TTT fields.
 *
 * Reference:
 *   - 4.6.6: Configure Endpoint
 *
 ****************************************************************************/

static int xhci_hub_update(FAR struct usbhost_xhci_s *priv,
                           FAR struct xhci_dev_s *dev,
                           FAR const uint8_t *hubdesc)
{
  FAR struct xhci_slot_ctx_s *slot = &dev->input->slot;
  uint16_t                    chars;
  uint32_t                    regval;

  chars = hubdesc[3] | (hubdesc[4] << 8);

  /* Keep Context Entries as the xHC has them */

  up_invalidate_dcache((uintptr_t)dev->ctx,
                       (uintptr_t)dev->ctx + sizeof(struct xhci_dev_ctx_s));

  regval  = le32toh(slot->ctx[0]) & ~XHCI_ST_CTX0_CTXENT_MASK;
  regval |= le32toh(dev->ctx->slot.ctx[0]) & XHCI_ST_CTX0_CTXENT_MASK;
  regval |= XHCI_ST_CTX0_HUB;
  slot->ctx[0] = htole32(regval);

  regval  = le32toh(slot->ctx[1]) & ~XHCI_ST_CTX1_PORTS_MASK;
  regval |= XHCI_ST_CTX1_PORTS_SET(hubdesc[2]);
  slot->ctx[1] = htole32(regval);

  if (dev->hport->speed == USB_SPEED_HIGH)
    {
      regval  = le32toh(slot->ctx[2]) & ~XHCI_ST_CTX2_TTT_MASK;
      regval |= XHCI_ST_CTX2_TTT_SET((chars >> 5) & 3);
      slot->ctx[2] = htole32(regval);
    }

  dev->input->input.ctx[0] = 0;
  dev->input->input.ctx[1] = htole32(XHCI_IN_CTX1_A(XHCI_SLOT_FLAG));

  up_flush_dcache((uintptr_t)dev->input,
                  (uintptr_t)dev->input +
                  sizeof(struct xhci_input_dev_ctx_s));

  return xhci_cmd_cfgep(priv, dev->slot,
                        up_addrenv_va_to_pa(dev->input), false);
}
#endif

/****************************************************************************
 * Name: xhci_dev_get
 *
 * Description:
 *   Get the device that owns an endpoint, NULL if the endpoint is not
 *   bound to a device slot (yet).
 *
 ****************************************************************************/

static FAR struct xhci_dev_s *xhci_dev_get(FAR struct usbhost_xhci_s *priv,
                                           FAR struct xhci_epinfo_s *epinfo)
{
  if (epinfo == NULL || epinfo->slot == 0 || epinfo->slot > priv->no_slots)
    {
      return NULL;
    }

  return &priv->devs[epinfo->slot - 1];
}

/****************************************************************************
 * Name: xhci_root_port
 *
 * Description:
 *   Get the root hub port below which a hub port is located.
 *
 ****************************************************************************/

static FAR struct xhci_rhport_s *
xhci_root_port(FAR struct usbhost_xhci_s *priv,
               FAR struct usbhost_hubport_s *hport)
{
#ifdef CONFIG_USBHOST_HUB
  while (!ROOTHUB(hport))
    {
      hport = hport->parent;
    }
#endif

  return &priv->rhport[hport->port];
}

/****************************************************************************
 * Name: xhci_speed_id
 *
 * Description:
 *   Convert USB speed to the xHCI Protocol Speed ID (default mapping).
 *
 ****************************************************************************/

static uint8_t xhci_speed_id(uint8_t speed)
{
  switch (speed)
    {
      case USB_SPEED_LOW:
        return XHCI_PORTSC_PS_LOW;

      case USB_SPEED_HIGH:
        return XHCI_PORTSC_PS_HIGH;

      case USB_SPEED_SUPER:
      case USB_SPEED_SUPER_PLUS:
        return XHCI_PORTSC_PS_SUPPER11;

      default:
        return XHCI_PORTSC_PS_FULL;
    }
}

/****************************************************************************
 * Name: xhci_address_set
 *
 * Description:
 *   Set address request.
 *
 *   If setaddr is true, then xHC issue a SET_ADDRESS request.
 *
 ****************************************************************************/

static int xhci_address_set(FAR struct usbhost_xhci_s *priv,
                            FAR struct xhci_dev_s *dev, bool setaddr)
{
  uint64_t ctx;

  ctx = up_addrenv_va_to_pa(dev->input);

  return xhci_cmd_setaddr(priv, dev->slot, ctx, !setaddr);
}

/****************************************************************************
 * Name: xhci_slot_init
 *
 * Description:
 *   Initialzie Device Slot data.
 *
 * Assumption:
 *   1. All slot resources already allocated.
 *   2. Port is in Enabled state.
 *
 * Reference:
 *   - 4.3.3. Device Slot Initialization
 *
 ****************************************************************************/

static int xhci_slot_init(FAR struct usbhost_xhci_s *priv,
                          FAR struct xhci_dev_s *dev)
{
  FAR struct usbhost_hubport_s *hport = dev->hport;
  uint32_t                      regval;
  uint16_t                      maxpkt;
  uintptr_t                     drdp;
#ifdef CONFIG_USBHOST_HUB
  FAR struct usbhost_hubport_s *child;
  FAR struct usbhost_hubport_s *parent;
  FAR struct xhci_dev_s        *hub;
  uint32_t                      route = 0;
#endif

  DEBUGASSERT(hport != NULL && dev->rhport != NULL);

  /* Step 1. The Input Context data structure already allocated.
   * Initialize all fields to 0.
   */

  memset(dev->input, 0, sizeof(struct xhci_input_dev_ctx_s));

  /* Step 2. Initialize the Input Control Context by setting the A0 and
   * A1 flags to 1 (Slot flag and EP0 flag).
   */

  regval = XHCI_IN_CTX1_A(XHCI_SLOT_FLAG) |
           XHCI_IN_CTX1_A(XHCI_EP0_FLAG);
  xhci_context_ctrl(priv, dev, 0, regval);

  /* Step 3. Initialize the Input Slot Context */

  regval = XHCI_ST_CTX0_CTXENT_SET(1) |
           XHCI_ST_CTX0_SPEED_SET(xhci_speed_id(hport->speed));

#ifdef CONFIG_USBHOST_HUB
  /* Route string: one nibble per hub tier below the root hub port, the
   * tier closest to the root in the lowest nibble.
   */

  for (child = hport; !ROOTHUB(child); child = child->parent)
    {
      route = (route << 4) | MIN(HPORT(child), 15);
    }

  regval |= XHCI_ST_CTX0_RTSTR_SET(route);
#endif

  dev->input->slot.ctx[0] = htole32(regval);

  /* Configure Root Hub Port Number (starts from 1).  The number of ports
   * is set later if the device turns out to be a hub.
   */

  regval = XHCI_ST_CTX1_RHPN_SET(RHPNDX(dev->rhport) + 1);
  dev->input->slot.ctx[1] = htole32(regval);

#ifdef CONFIG_USBHOST_HUB
  /* A low- or full-speed device below a high-speed hub talks through the
   * transaction translator of the nearest high-speed hub.
   */

  if (hport->speed == USB_SPEED_LOW || hport->speed == USB_SPEED_FULL)
    {
      child = hport;
      for (parent = hport->parent;
           parent != NULL && parent->speed != USB_SPEED_HIGH;
           parent = parent->parent)
        {
          child = parent;
        }

      if (parent != NULL)
        {
          hub = xhci_dev_get(priv, parent->ep0);
          if (hub == NULL)
            {
              return -ENODEV;
            }

          regval = XHCI_ST_CTX2_TTHUB_SET(hub->slot) |
                   XHCI_ST_CTX2_TTPORT_SET(HPORT(child));
          dev->input->slot.ctx[2] = htole32(regval);
        }
    }
#endif

  /* Step 4. the Transfer Ring for the Default Control Endpoint is already
   * allocated.
   */

  drdp = up_addrenv_va_to_pa(dev->epinfo[0]->td.ring);

  /* Step 5. Initialize the Input default control Endpoint 0 Context */

  if (hport->speed == USB_SPEED_SUPER || hport->speed == USB_SPEED_SUPER_PLUS)
    {
      maxpkt = 512;
    }
  else if (hport->speed == USB_SPEED_HIGH)
    {
      /* For high-speed, we must use 64 bytes */

      maxpkt = 64;
    }
  else
    {
      /* Eight will work for both low- and full-speed */

      maxpkt = 8;
    }

  DEBUGASSERT(drdp != 0);
  xhci_ep_configure(priv,
                    &dev->input->ep[0],
                    XHCI_EPTYPE_CTRL, maxpkt,
                    0, drdp,
                    0, 0);

  /* Step 6. The output Device Context data structure already allocated.
   * Initialize all fields to 0.
   */

  memset(dev->ctx, 0, sizeof(struct xhci_dev_ctx_s));

  /* Flush Device input context */

  up_flush_dcache((uintptr_t)dev->input,
                  (uintptr_t)dev->input +
                  sizeof(struct xhci_input_dev_ctx_s));

  /* Step 7. Load the appropriate (Device Slot ID) entry in the Device
   * Context Base Address Array with a pointer to the Output Device
   * Context data structure
   */

  xhci_dcbaa_set(priv, dev->slot, up_addrenv_va_to_pa(dev->ctx));

  return OK;
}

